<?php $title='Profile';require __DIR__.'/_layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!password_verify($_POST['current_password'],current_user()['id'] ? db()->query("SELECT password_hash FROM users WHERE id=".(int)current_user()['id'])->fetchColumn() : ''))exit('Current password incorrect');if(strlen($_POST['password'])<8)exit('Password must be 8+ chars');db()->prepare("UPDATE users SET password_hash=? WHERE id=?")->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),current_user()['id']]);flash('success','Password changed.');redirect('profile.php');}?><h1>Profile</h1><p><?=e(current_user()['name'])?> · <?=e(current_user()['email'])?></p><form class="form" method="post"><?=csrf_field()?><label>Current password</label><input type="password" name="current_password" required><label>New password</label><input type="password" name="password" minlength="8" required><button>Change password</button></form><?php require __DIR__.'/_footer.php';?>